    "value": {
      "rainTaxi": {
        "title": "雨天打车",
        "weatherText": "小雨 22°C",
        "etaValue": 6,
        "etaUnit": "分钟",
        "queueText": "前方 3 人",
        "routeHint": "雨中出发",
        "actionText": "导航",
        "icon": "assets/rainy-taxi-icon.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "rainy_taxi_icon",
      "src": "assets/rainy-taxi-icon.png",
      "use": "rainy taxi icon",
      "description": "雨天打车图标，可用于表达雨伞、出租车或雨中出行的轻量主视觉。",
      "bindTo": "/rainTaxi/icon",
      "static": true
    }
  ]
}

